def _lane_width_at_y(poly, y):
    """차선 polygon의 주어진 Y좌표에서 가로 폭 계산 (원근 반영).
    polygon 변을 따라 y와 교차하는 x좌표들을 구하고,
    최소/최대 x 차이를 반환한다.
    y가 polygon의 [y_min, y_max] 범위를 벗어나면 가장 가까운 경계로 clamp
    (차량 bbox가 이미지 하단에 닿아 polygon 범위 밖으로 나갈 때 대응)."""
    pts = poly.reshape(-1, 2)
    poly_ys = pts[:, 1].astype(float)
    y_min, y_max = float(poly_ys.min()), float(poly_ys.max())
    y = max(y_min, min(y_max, float(y)))
    n = len(pts)
    xs = []
    for j in range(n):
        p1 = pts[j]
        p2 = pts[(j + 1) % n]
        y1, y2 = p1[1], p2[1]
        if y1 == y2:
            continue
        if min(y1, y2) <= y <= max(y1, y2):
            t = (y - y1) / (y2 - y1)
            x = p1[0] + t * (p2[0] - p1[0])
            xs.append(x)
    if len(xs) < 2:
        return 0
    return max(xs) - min(xs)


def _lane_xrange_at_y(poly, y):
    """차선 polygon의 주어진 Y좌표에서의 x 범위 (min_x, max_x). 없으면 None.
    (원근 반영: 변과 y 교차하는 x들의 최소/최대. y는 polygon 범위로 clamp)"""
    pts = poly.reshape(-1, 2)
    poly_ys = pts[:, 1].astype(float)
    y = max(float(poly_ys.min()), min(float(poly_ys.max()), float(y)))
    n = len(pts)
    xs = []
    for j in range(n):
        p1, p2 = pts[j], pts[(j + 1) % n]
        y1, y2 = p1[1], p2[1]
        if y1 == y2:
            continue
        if min(y1, y2) <= y <= max(y1, y2):
            t = (y - y1) / (y2 - y1)
            xs.append(p1[0] + t * (p2[0] - p1[0]))
    if len(xs) < 2:
        return None
    return min(xs), max(xs)


def calc_lane_occupancy(bbox, cam_lanes):
    """정차차량 bbox가 '어느 차선에 얼마나 걸쳐 있는지' 계산.
    bbox 폭을 100%로 두고, bbox와 각 차선의 가로 겹침폭 / bbox폭 → 차선별 비율.
    (한 차선 안에 똑바로 정차하면 그 차선 ~100%, 경계에 걸치면 양쪽으로 나뉨)
    bbox: [x1, y1, x2, y2]
    Returns: (lane_idx, [lane1_ratio, lane2_ratio, ...])
      lane_idx: 차량 중심이 위치한 차선(0-based), 없으면 None
      리스트: bbox 폭 대비 각 차선 걸침 비율 0.0~1.0 (합 ≤ 1.0, 도로 밖 부분은 제외)"""
    x1, _, x2, y2 = bbox[0], bbox[1], bbox[2], bbox[3]
    bot_y = y2
    cx, cy = (x1 + x2) / 2, (bbox[1] + y2) / 2
    bbox_w = max(1e-6, x2 - x1)   # 분모: bbox 가로폭(=100%)

    per_lane = []
    for lane_poly in cam_lanes:
        rng = _lane_xrange_at_y(lane_poly, bot_y)
        if rng is None:
            per_lane.append(0.0); continue
        lx, rx = rng
        overlap = max(0.0, min(x2, rx) - max(x1, lx))   # bbox ∩ 차선 가로폭
        per_lane.append(round(min(float(overlap / bbox_w), 1.0), 3))

    # 차량이 주로 속한 차선(중심점 기준)
    lane_idx = None
    for idx, lane_poly in enumerate(cam_lanes):
        if cv2.pointPolygonTest(lane_poly, (float(cx), float(cy)), False) >= 0:
            lane_idx = idx
            break
    return lane_idx, per_lane


def calc_lane_speed ( speed_lane ):

    if sum(speed_lane) ==0 or len(speed_lane) ==0:
        return 999,999

    
    else:
        return int(sum(speed_lane)/len(speed_lane)),int(len(speed_lane))
